/**
 * Tool names the agentic Slack watcher honors.
 * Mounted tools are `<namespace>__<name>`; bare names work too.
 */
import { isAbsolute } from "node:path";
import { isRecord } from "../../internal/is-record.js";
import { SLACK_FILE_ALT_TEXT_MAX_LEN, SLACK_FILE_INITIAL_COMMENT_MAX_LEN, SLACK_STATUS_MAX_LEN, } from "./constants.js";
export const POST_UPDATE = "post-update";
export const POST_FILE = "post-file";
export const POST_CARD = "post-card";
export const REACT = "react";
export const SET_STATUS = "set-status";
export const EDIT_MESSAGE = "edit-message";
export const DELETE_MESSAGE = "delete-message";
export const MAX_UPDATE_CHARS = 900;
export const MAX_REASON_CHARS = 200;
const OWNED_SIGNALS = [
    POST_UPDATE,
    POST_FILE,
    POST_CARD,
    REACT,
    SET_STATUS,
    EDIT_MESSAGE,
    DELETE_MESSAGE,
];
const EMOJI_NAME = /^[a-z0-9_+-]{1,50}$/;
export function emojiName(raw) {
    const name = raw.replace(/^:+|:+$/g, "").toLowerCase();
    if (!EMOJI_NAME.test(name)) {
        return undefined;
    }
    return name;
}
export function isSignal(toolName, signal) {
    return toolName === signal || toolName.endsWith(`__${signal}`);
}
export function isOwnedSignal(toolName) {
    return OWNED_SIGNALS.some((signal) => isSignal(toolName, signal));
}
function asObject(output) {
    if (typeof output === "string") {
        const trimmed = output.trim();
        if (!trimmed.startsWith("{")) {
            return undefined;
        }
        try {
            const parsed = JSON.parse(trimmed);
            if (isRecord(parsed)) {
                return parsed;
            }
        }
        catch {
            return undefined;
        }
        return undefined;
    }
    return isRecord(output) ? output : undefined;
}
export function publishedText(output) {
    const value = asObject(output);
    if (value === undefined) {
        return undefined;
    }
    const message = value.message;
    if (typeof message !== "string") {
        return undefined;
    }
    const text = message.trim();
    if (text === "" || text.length > MAX_UPDATE_CHARS) {
        return undefined;
    }
    return text;
}
export function parseUpdate(output) {
    const message = publishedText(output);
    if (message === undefined) {
        return undefined;
    }
    const ts = asObject(output)?.ts;
    if (typeof ts !== "string") {
        return { message };
    }
    const trimmed = ts.trim();
    return trimmed === "" ? { message } : { message, ts: trimmed };
}
function cardStatus(value) {
    if (value === "pending" || value === "in_progress" || value === "complete" || value === "error") {
        return value;
    }
    return undefined;
}
export function parseCard(output) {
    const value = asObject(output);
    if (value === undefined) {
        return undefined;
    }
    const id = value.id;
    const title = value.title;
    const status = cardStatus(value.status);
    const details = value.details;
    if (typeof id !== "string" || id.trim() === "") {
        return undefined;
    }
    if (typeof title !== "string" || title.trim() === "") {
        return undefined;
    }
    if (status === undefined) {
        return undefined;
    }
    const task = {
        type: "task_update",
        id: id.trim(),
        title: title.trim(),
        status,
    };
    if (typeof details === "string" && details.trim() !== "") {
        task.details = details.trim();
    }
    return task;
}
export function parseReaction(output) {
    const value = asObject(output);
    if (value === undefined) {
        return undefined;
    }
    if (typeof value.emoji !== "string") {
        return undefined;
    }
    const emoji = emojiName(value.emoji);
    if (emoji === undefined) {
        return undefined;
    }
    const reaction = { emoji };
    if (typeof value.ts === "string" && value.ts.trim() !== "") {
        reaction.ts = value.ts.trim();
    }
    return reaction;
}
export function parseEdit(output) {
    const value = asObject(output);
    if (value === undefined || typeof value.ts !== "string") {
        return undefined;
    }
    const ts = value.ts.trim();
    if (ts === "") {
        return undefined;
    }
    const message = publishedText(output);
    if (message === undefined) {
        return undefined;
    }
    return { ts, message };
}
export function parseDelete(output) {
    const value = asObject(output);
    if (value === undefined) {
        return undefined;
    }
    if (typeof value.ts !== "string" || typeof value.reason !== "string") {
        return undefined;
    }
    const ts = value.ts.trim();
    const reason = value.reason.trim();
    if (ts === "" || reason === "" || reason.length > MAX_REASON_CHARS) {
        return undefined;
    }
    return { ts, reason };
}
export function parseStatus(output) {
    const value = asObject(output);
    if (value === undefined || typeof value.status !== "string") {
        return undefined;
    }
    if (value.status.length > SLACK_STATUS_MAX_LEN) {
        return undefined;
    }
    return value.status;
}
function boundedText(value, max) {
    if (typeof value !== "string") {
        return undefined;
    }
    const text = value.trim();
    if (text === "" || text.length > max) {
        return undefined;
    }
    return text;
}
export function parseStagedFile(output) {
    const value = asObject(output);
    if (value === undefined) {
        return undefined;
    }
    const path = value.path;
    const name = value.name;
    const workspace = value.workspace;
    if (typeof path !== "string" || path === "" || !isAbsolute(path)) {
        return undefined;
    }
    if (typeof name !== "string" || name === "") {
        return undefined;
    }
    if (typeof workspace !== "string" || workspace === "") {
        return undefined;
    }
    const staged = { path, name, workspace };
    const altTxt = boundedText(value.alt_txt, SLACK_FILE_ALT_TEXT_MAX_LEN);
    const initialComment = boundedText(value.initial_comment, SLACK_FILE_INITIAL_COMMENT_MAX_LEN);
    if (altTxt !== undefined) {
        staged.altTxt = altTxt;
    }
    if (initialComment !== undefined) {
        staged.initialComment = initialComment;
    }
    return staged;
}
